<?php

declare(strict_types=1);

namespace App\Domain\Money;

/**
 * Decimal arithmetic over money based on bcmath.
 *
 * Intermediate computations are executed without rounding (scale >= 24);
 * the final rounding of event cost is HALF_UP to 6 decimal places.
 */
final class MoneyMath
{
    /** Precision of intermediate computations (well in excess of the needed 18 digits). */
    public const SCALE = 24;

    public const CENTS_SCALE = 6;

    public static function add(string ...$values): string
    {
        $sum = '0';
        foreach ($values as $v) {
            $sum = bcadd($sum, $v, self::SCALE);
        }
        return $sum;
    }

    public static function sub(string $a, string $b): string
    {
        return bcsub($a, $b, self::SCALE);
    }

    public static function mul(string $a, string $b): string
    {
        return bcmul($a, $b, self::SCALE);
    }

    public static function div(string $a, string $b): string
    {
        return bcdiv($a, $b, self::SCALE);
    }

    public static function sum(array $values): string

    /**
     * HALF_UP rounding to $scale decimal places (2.5 → 3; for negative numbers — away from zero).
     */
    public static function round(string $value, int $scale = self::CENTS_SCALE): string
    {
        $value = trim($value);
        if ($value === '' || $value === '-' || $value === '+') {
            throw new \InvalidArgumentException('Empty numeric value: '.$value);
        }
        $negative = str_starts_with($value, '-');
        if ($negative || str_starts_with($value, '+')) {
            $value = substr($value, 1);
        }
        if (!str_contains($value, '.')) {
            $value .= '.';
        }
        [$int, $frac] = explode('.', $value, 2);
        if ($int === '') {
            $int = '0';
        }
        $frac = str_pad($frac, $scale + 1, '0');
        $keep = substr($ frac, 0, $scale);
        $nextDigit = $frac[$scale];
        $base = $int.'.'.$keep;
        $result = $nextDigit >= '5'
            ? bcadd($base, '0.'.str_repeat('0', max(0, $scale - 1)).'1', $scale)
            : bcadd($base, '0', $scale);
        if ($negative && bccomp($result, '0', $scale) > 0) {
            $result = '-'.$result;
        }
        return $result;
    }
}
