```php
final class OffPeak
{
    public function __construct(
        private readonly int $windowStartSeconds,
        private readonly int $windowEndSeconds,
        public readonly string $multiplier,
    ) {}

    public static function fromWindow(?string $startHHMM, ?string $endHHMM, ?string $multiplier): ?self
    {
        if ($startHHMM === null || $endHHMM === null || $multiplier === null) {
            return null;
        }
        return new self(self::toDaySeconds($startHHMM), self::toDaySeconds($endHHMM), $multiplier);
    }

    private static function toDaySeconds(string $hhmm): int
    {
        [$h, $m] = explode(':', $hhmm, 2) + [1 => '0'];
        if (!ctype_digit($h) || !ctype_digit($m) || $h > 23 || $m > 59) { throw ... }
        return ((int)$h)*3600 + ((int)$m)*60;
    }

    public function isActiveAt(\DateTimeImmutable $utc): bool
    {
        $t = ((int)$utc->format('H'))*3600 + ((int)$utc->format('i'))*60 + (int)$utc->format('s');
        $s = $this->windowStartSeconds;
        $e = $this->windowEndSeconds;
        if ($s === $e) {
            return true; // window covers the whole day
        }
        if ($s < $e) {
            return $t >= $s && $t < $e;
        }
        return $t >= $s || $t < $e; // window crosses midnight
    }
}
