EventPricer:

```php
final class EventPricer
{
    public function price(PriceRowSpec $row, TokenUsage $usage, ?OffPeak $offPeak, \DateTimeImmutable $eventTimeUtc): string
    {
        $base = match (true) {
            $row->isPerToken() => MoneyMath::add(
                MoneyMath::mul((string)$usage->input, $row->rates['input']),
                MoneyMath::mul((string)$usage->output, $row->rates['output']),
                MoneyMath::mul((string)$usage->cacheRead, $row->rates['cache_read']),
                MoneyMath::mul((string)$usage->cacheWrite, $row->rates['cache_write']),
            ),
            $row->isUnified() => MoneyMath::mul((string)$usage->total(), $row->rates['any']),
            default => throw new \DomainException('unknown pricing scheme: '.$row->unit),
        };

        $cost = MoneyMath::div($base, '1000000');
        if ($offPeak !== null && $offPeak->isActiveAt($eventTimeUtc)) {
            $cost = MoneyMath::mul($cost, $offPeak->multiplier);
        }

        return MoneyMath::round($cost);
    }
}
