/** @extends EntityRepository<UsageEvent> */
final class UsageEventRepository extends EntityRepository
{
    /** @return UsageEvent[] */
    public function findByStatus(string $status): array
    {
        return $this->createQueryBuilder('e')
            ->where('e.status = :status')
            ->orderBy('e.id', 'ASC')
            ->getQuery()->getResult();
    }

    /** @return UsageEvent[] */
    public function findRatedBetween(?\DateTimeImmutable $from, ?\DateTimeImmutable $to): array
    {
        $qb = $this->createQueryBuilder('e')
            ->where('e.status = :status')->setParameter('status', 'rated');
        if ($from !== null) $qb->andWhere('e.ts >= :from')->setParameter('from', $from);
        if ($to !== null) $qb->andWhere('e.ts < :to')->setParameter('to', $to);
        return $qb->orderBy('e.ts','ASC')->addOrderBy('e.id','ASC')->getQuery()->getResult();
    }

    /** @return UsageEvent[] */
    public function findRatedBy(string $provider, string $model, \DateTimeImmutable $priceValidFrom): array
    {
        return $this->createQueryBuilder('e')
            ->where('e.status = :status')->setParameter('status','rated')
            ->andWhere('e.provider = :p')->setParameter('p',$provider)
            ->andWhere('e.model = :m')->setParameter('m',$model)
            ->andWhere('e.priceValidFrom = :v')->setParameter('v',$priceValidFrom)
            ->getQuery()->getResult();
    }
}
