final class PriceCatalogImporter
{
    public function __construct(
        private EntityManagerInterface $em,
        private PriceFileParser $parser,
    ) {}

    /** @throws ImportException */
    public function import(string $path): void
    {
        $file = $this->parser->parse($path);

        $this->em->transactional(function () use ($file): void {
            foreach ($file->providers as $p) {
                $entity = $this->em->getRepository(Provider::class)->findOneBy(['code' => $p->code]);
                if ($entity === null) {
                    $entity = new Provider();
                    $entity->code = $p->code;
                    $this->em->persist($entity);
                }
                $this->applyProvider($entity, $p); // update if different
            }

            foreach ($file->models as $m) {
                $entity = $this->em->getRepository(Model::class)->findOneBy(['provider' => $m->provider, 'code' => $m->code]);
                if ($entity === null) {
                    $entity = new Model();
                    $entity->provider = $m->provider;
                    $entity->code = $m->code;
                    $this->em->persist($entity);
                }
            }

            $modelsInDb = ... // check that the pair is known
            foreach ($file->prices as $pr) {
                $this->upsertPriceRow($pr);
            }

            $this->em->flush();
        });
    }
}
