final class PriceFileParser
{
    /** @throws InputException */
    public function parse(string $path): ParsedPrices
    {
        if (!is_file($path) || !is_readable($path)) {
            throw new InputException(sprintf('Файл не найден или нечитаем: %s', $path));
        }
        $raw = file_get_contents($path);
        if ($raw === false) {
            throw new InputException(sprintf('Не удалось прочитать файл: %s', $path));
        }
        try {
            $data = json_decode($raw, true, 512, JSON_THROW_ON_ERROR);
        } catch (\JsonException $e) {
            throw new InputException(sprintf('Некорректный JSON: %s', $e->getMessage()), previous: $e);
        }
        if (!is_array($data)) {
            throw new InputException('Корень файла должен быть JSON-объектом');
        }

        return new ParsedPrices(
            providers: $this->parseProviders(is_array($data['providers'] ?? null) ? $data['providers'] : []),
            models: $this->parseModels(is_array($data['models'] ?? null) ? $data['models'] : []),
            prices: $this->parsePrices(is_array($data['prices'] ?? null) ? $data['prices'] : []),
        );
    }
