final class PriceCatalogImporter
{
    public function __construct(
        private readonly PriceFileParser $parser,
        private readonly PriceRowApplier $applier,
        private readonly EntityManagerInterface $em,
    ) {}

    /** @throws InputException */
    public function import(string $path): void
    {
        $file = $this->parser->parse($path);
        $this->validate($file);

        $em = $this->em;
        $em->transactional(function () use ($file): void {
            foreach ($file->providers as $p) $this->applier->upsertProvider($p);
            foreach ($file->models as $m) $this->applier->upsertModel($m);
            foreach ($file->prices as $r) $this->applier->upsertPriceRow($r);
            $this->em->flush();
        });
    }

    private function validate(ParsedPrices $file): void
    {
        $providersInFile = array_map(fn(ProviderRecord $p) => $p->code, $file->providers);
        $modelsInFile = array_map(fn(ModelRecord $m) => $m->provider."\x1f".$m->code, $file->models);

        // Duplicate provider codes in file
        ... check duplicates → InputException

        $providerRepo = $this->em->getRepository(Provider::class);
        $modelRepo = $this->em->getRepository(Model::class);
        foreach ($file->prices as $i => $r) {
            $providerOk = in_array($r->provider, $providersInFile, true) || $providerRepo->findOneBy(['code' => $r->provider]) !== null;
