final class EventRater
{
    public function __construct(
        private readonly EntityManagerInterface $em,
        private readonly EventPricer $pricer,
    ) {}

    /** @throws \Doctrine\ORM\ORMException */
    public function rateAll(): RateResult
    {
        $em = $this->em;
        $eventRepo = $em->getRepository(UsageEvent::class);
        $priceRepo = $em->getRepository(PriceRow::class);

        $rated = 0;
        $unrated = [];
        /** @var array<string, ?OffPeak> $offPeaks */
        $offPeaks = [];

        foreach ($eventRepo->findByStatus(UsageEvent::STATUS_UNRATED) as $event) {
            $row = $priceRepo->latestAtOrBefore($event->provider, $event->model, $event->ts);
            if ($row === null) {
                $unrated[] = $event;
                continue;
            }
            $offPeak = $offPeaks[$event->provider]
                ??= $this->offPeakFor($event->provider, $offPeaks);
            $cost = $this->pricer->price(
                PriceRowMapper::toSpec($row),
                TokenUsage::create($event->tokensInput, $event->tokensOutput, $event->tokensCacheRead, $event->tokensCacheWrite),
                $offPeak,
                $event->ts,
            );
            $event->status = UsageEvent::STATUS_RATED;
            $event->cost = $cost;
            $event->priceValidFrom = $row->validFrom;
            $rated++;
        }

        $em->flush();
        return new RateResult($rated, $unrated);
    }

    private function offPeakFor(string $code): ?OffPeak
    {
        $provider = $this->em->getRepository(Provider::class)->findOneBy(['code' => $code]);
        if ($provider === null) return null;
        return OffPeak::fromWindow($provider->offPeakStart, $provider->offPeakEnd, $provider->offPeakMultiplier);
    }
}
