```php
final class Repricer
{
    public function __construct(
        private readonly EntityManagerInterface $em,
        private readonly PriceFileParser $parser,
        private readonly PriceRowApplier $applier,
        private readonly EventPricer $pricer,
    ) {}

    /** @throws InputException */
    public function reprice(string $path): RepriceResult
    {
        $file = $this->parser->parse($path);
        if ($file->prices === []) {
            throw new InputException('В файле нет строк цен (секция "prices" пуста)');
        }

        $em = $this->em;
        $this->assertCatalog($file);

        // Rows being "replaced" — those keys that already exist in the DB
        $replaced = [];
        foreach ($file->prices as $record) {
            $exists = $em->getRepository(PriceRow::class)->findOneBy([
                'provider' => $record->provider,
                'model' => $record->model,
                'validFrom' => $record->validFrom,
            ]);
            if ($exists !== null) {
                $replaced[] = $record;
            }
        }

        $em->transactional(function () use ($file): void {
            foreach ($file->prices as $record) {
                $this->applier->upsertPriceRow($record);
            }
            $this->em->flush();
        });

        return $this->recalculate($replaced);
    }

    private function assertCatalog(ParsedPrices $file): void
    {
        $providerRepo = $this->em->getRepository(Provider::class);
        $modelRepo = $this->em->getRepository(Model::class);
        foreach ($file->prices as $i => $record) {
            if ($providerRepo->findOneBy(['code' => $record->provider]) === null) {
                throw new InputException(sprintf('Строка цен %d: провайдер "%s" отсутствует в справочнике', $i + 1, $record->provider));
            }
            if ($modelRepo->findOneBy(['provider' => $record->provider, 'code' => $record->model]) === null) {
                throw new InputException(sprintf('Строка цен %d: модель "%s/%s" отсутствует в справочнике', $i + 1, $record->provider, $record->model));
            }
        }
    }

    private function recalculate(array $replaced): RepriceResult
    {
        $em = $this->em;
        $count = 0;
        $delta = '0';
        $offPeaks = [];

        $em->transactional(function () use ($replaced, &$count, &$delta, &$offPeaks): void {
            $eventRepo = $em->getRepository(UsageEvent::class);
            $priceRepo = $em->getRepository(PriceRow::class);

            foreach ($replaced as $key) {
                /** @var UsageEvent[] $events */
                $events = $eventRepo->findRatedBy($key->provider, $key->model, $key->validFrom);
                foreach ($events as $event) {
                    $oldCost = (string) $event->cost;

                    $row = $priceRepo->latestAtOrBefore($event->provider, $event->model, $event->ts);
                    if ($row !== null) {
                        $event->status = UsageEvent::STATUS_RATED;
                        $event->cost = $this->pricer->price(
                            PriceRowMapper::toSpec($row),
                            TokenUsage::create($event->tokensInput, $event->tokensOutput, $event->tokensCacheRead, $event->tokensCacheWrite),
                            $this->offPeakCached($event->provider, $offPeaks),
                            $event->ts,
                        );
                        $event->priceValidFrom = $row->validFrom;
                        $newCost = $event->cost;
                    } else {
                        $event->status = UsageEvent::STATUS_UNRATED;
                        $event->cost = null;
                        $event->priceValidFrom = null;
                        $newCost = '0';
                    }

                    $count++;
                    $delta = bcadd($delta, bcsub($newCost, $oldCost, 6), 6);
                }
            }

            $em->flush();
        });

        return new RepriceResult($count, MoneyMath::normalize6($delta));
    }
}
```

